 basis text:=current_setting('ecr.stage0405_owner_ref',true); item jsonb;
BEGIN
 IF p IS DISTINCT FROM expected OR coalesce(basis,'')!~'^owner-decision:sha256:[a-f0-9]{64}$' THEN RAISE EXCEPTION 'EXACT_STAGE0405_OWNER_DECISION_REQUIRED'; END IF;
 IF current_user<>'profitia_access_owner' OR NOT EXISTS(SELECT 1 FROM profitia_access.installation WHERE singleton AND environment='development'
 AND project_id=p->'identity'->>'projectId' AND branch_id=p->'identity'->>'branchId' AND database_name=current_database())
 OR to_regclass('profitia_e1_authority.ecr_continuity_policy') IS NULL THEN RAISE EXCEPTION 'EXACT_IDENTITY_STAGE0405_INSTALLATION_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('ecr-stage0405-owner-enrollment',0));
 IF EXISTS(SELECT 1 FROM profitia_services.read_grants WHERE grant_id=(p->'identity'->'newGrant'->>'grantId')::uuid)
 OR EXISTS(SELECT 1 FROM profitia_e1_authority.ecr_continuity_policy) THEN RAISE EXCEPTION 'ECR_STAGE0405_EXISTS_RECONCILE'; END IF;
 IF NOT EXISTS(SELECT 1 FROM profitia_e1_authority.source_components c JOIN profitia_services.runtime_bindings b USING(login_role)
 WHERE c.component_id=p->>'componentId' AND c.key_id=p->'identity'->>'keyId' AND c.application_id=p->>'applicationId' AND c.login_role=p->'identity'->>'role'
 AND c.status='ACTIVE' AND b.status='ACTIVE' AND c.expires_at>clock_timestamp() AND b.expires_at>clock_timestamp()
 AND b.service_id=(p->'identity'->>'serviceId')::uuid AND b.binding_id=(p->'identity'->>'bindingId')::uuid
 AND encode(public.digest(convert_to(c.public_key,'UTF8'),'sha256'),'hex')=p->'identity'->>'publicKeySha256')
 THEN RAISE EXCEPTION 'CURRENT_OWN_ECR_COMPONENT_REQUIRED'; END IF;
 IF (SELECT count(*) FROM profitia_services.read_grants WHERE login_role=p->'identity'->>'role' AND organisation_id=(p->>'organisationId')::uuid
 AND grant_id IN('e7de5248-bfba-4a6c-b1c4-8bd987cab70c','031c143f-58d2-4668-8818-7c2d1327e3df')
 AND status='ACTIVE' AND effect='ALLOW' AND operation='knowledge.read' AND feature='market' AND expires_at>clock_timestamp())<>2
 THEN RAISE EXCEPTION 'ORIGINAL_TWO_SCHEDULE_GRANTS_REQUIRED'; END IF;
 INSERT INTO profitia_services.read_grants(grant_id,login_role,organisation_id,operation,feature,resource_id,effect,status,source_ref,expires_at)
 VALUES((p->'identity'->'newGrant'->>'grantId')::uuid,p->'identity'->>'role',(p->>'organisationId')::uuid,'knowledge.read','market','api.eia.series-observations','ALLOW','ACTIVE',basis,(p->'identity'->'newGrant'->>'initialExpiry')::timestamptz);
 INSERT INTO profitia_e1_authority.ecr_continuity_policy(application_id,component_id,login_role,organisation_id,grant_ids,resources,status,version,owner_basis,lease_until)
 VALUES(p->>'applicationId',p->>'componentId',p->'identity'->>'role',(p->>'organisationId')::uuid,
 ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(p->'identity'->'renewedGrantIds')),
 ARRAY['api.eia.publication-calendar','api.commodities-sh.publication-calendar','api.eia.series-observations'],'ACTIVE',1,basis,clock_timestamp());
 GRANT USAGE ON SCHEMA profitia_e1_authority TO economic_calendar_development_ingest;
END $activate$;
